from pathlib import Path
root=Path(__file__).resolve().parent
p=root/'index.html'
h=p.read_text(encoding='utf-8')
if "home.id='mpHome'" in h: raise SystemExit('Mise à jour déjà appliquée.')
if 'id="workspace"' not in h: raise SystemExit('Version HTML incompatible.')
js="const home=document.createElement('section'),catalog=document.createElement('section');home.id='mpHome';catalog.id='mpCatalogue';const workspace=$('workspace');workspace.before(home,catalog);let route='home';function make(t,text,cls){const n=document.createElement(t);if(text)n.textContent=text;if(cls)n.className=cls;return n;}function button(text,fn){const b=make('button',text,'btn primary');b.type='button';b.addEventListener('click',fn);return b;}function cards(host,list){host.replaceChildren();list.forEach(p=>{const c=make('article',null,'panel');c.append(make('h3',p.name),make('p',p.desc,'muted'),make('p',p.positions.map(x=>x.ticker).join(' · '),'muted'),button('Ouvrir l’analyse →',()=>{selected=p.id;show('detail');result=null;render();refresh();}));host.append(c);});}function show(value){route=value;home.classList.toggle('hidden',value!=='home');catalog.classList.toggle('hidden',value!=='catalog');workspace.classList.toggle('hidden',value!=='detail');$('method').classList.toggle('hidden',value!=='method');document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.mpRoute===(value==='detail'?'catalog':value)));}const hero=make('div',null,'hero');hero.append(make('h2','Des portefeuilles pour aller plus loin'),make('p','Découvrez les stratégies et retrouvez votre sélection.'),button('Explorer les portefeuilles',()=>show('catalog')));home.append(hero);const hp=make('div',null,'mpPad');hp.append(make('h2','Votre sélection'));const fav=make('div',null,'mpGrid');hp.append(fav,make('h2','À découvrir'));const featured=make('div',null,'mpGrid');hp.append(featured);home.append(hp);function homeRender(){const list=portfolios.filter(p=>favorites.includes(p.id));cards(fav,list);if(!list.length)fav.append(make('p','Aucun favori pour le moment. Ajoutez une stratégie aux favoris depuis sa fiche.','muted'));cards(featured,portfolios.filter(p=>!favorites.includes(p.id)));}catalog.className='mpPad';catalog.append(make('h1','Les portefeuilles'),make('p','Explorez les allocations par nom, thème ou ticker, puis ouvrez leur fiche détaillée.','muted'));const tools=make('div',null,'panel toolbar'),query=make('input'),filter=make('select'),sort=make('select');query.placeholder='Nom, thème ou ticker…';query.setAttribute('aria-label','Recherche catalogue');filter.setAttribute('aria-label','Filtre catalogue');sort.setAttribute('aria-label','Tri catalogue');[['all','Toutes les stratégies'],['favorites','Mes favoris']].forEach(([v,t])=>{const o=make('option',t);o.value=v;filter.append(o);});[['default','Ordre de présentation'],['name','Nom A → Z'],['size','Nombre de titres']].forEach(([v,t])=>{const o=make('option',t);o.value=v;sort.append(o);});tools.append(query,filter,sort);catalog.append(tools);const count=make('p',null,'muted'),grid=make('div',null,'mpGrid');count.setAttribute('aria-live','polite');catalog.append(count,grid);function draw(){const q=query.value.toLowerCase().trim();let list=portfolios.filter(p=>(filter.value!=='favorites'||favorites.includes(p.id))&&(p.name+' '+p.desc+' '+p.positions.map(x=>x.ticker).join(' ')).toLowerCase().includes(q));if(sort.value==='name')list.sort((a,b)=>a.name.localeCompare(b.name));if(sort.value==='size')list.sort((a,b)=>b.positions.length-a.positions.length);count.textContent=list.length+' stratégie(s)';cards(grid,list);if(!list.length)grid.append(make('p','Aucun résultat. Modifiez votre recherche.','muted'));}query.addEventListener('input',draw);filter.addEventListener('change',draw);sort.addEventListener('change',draw);const nav=Array.from(document.querySelectorAll('nav button'));let all=0;nav.forEach(b=>{const value=b.dataset.page==='all'?(all++===0?'home':'catalog'):b.dataset.page==='method'?'method':'home';b.dataset.mpRoute=value;b.addEventListener('click',e=>{e.stopImmediatePropagation();homeRender();draw();show(value);},true);});['discover','allPortfolios'].forEach(id=>{const b=document.getElementById(id);if(b)b.addEventListener('click',e=>{e.stopImmediatePropagation();draw();show('catalog');},true);});$('back').addEventListener('click',e=>{e.stopImmediatePropagation();show('home');},true);const back=button('← Retour aux portefeuilles',()=>{draw();show('catalog');});workspace.prepend(back);$('search').addEventListener('input',e=>{e.stopImmediatePropagation();query.value=$('search').value;draw();show('catalog');},true);const previousRender=render;render=function(){previousRender();homeRender();draw();};homeRender();draw();show('home');"
end=h.rfind('})();')
if end<0: raise SystemExit('Structure JavaScript incompatible.')
h=h[:end]+js+'\n'+h[end:]
h=h.replace('</style>', '.mpPad{padding:24px}.mpGrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px;margin:20px 0}#mpCatalogue .toolbar input,#mpCatalogue .toolbar select{flex:1;min-width:160px}@media(max-width:1000px){.mpGrid{grid-template-columns:repeat(2,1fr)}}@media(max-width:650px){.mpGrid{grid-template-columns:1fr}.mpPad{padding:16px}}</style>',1)
b=root/'index.html.avant-v6.bak'
if not b.exists(): b.write_bytes(p.read_bytes())
p.write_text(h,encoding='utf-8')
print('V6 appliquée. Rechargez la page sans cache. Serveur et KPI inchangés.')
